import{_ as o,a0 as l,w as d,s as r,I as i,x as s,a1 as a,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Linux 中切換相同程序的不同版本 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中切換相同程序的不同版本 | LCTT (201808) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中切換相同程序的不同版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中切換相同程序的不同版本 | LCTT (201808) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201808/20180813 How To Switch Between Different Versions Of Commands In Linux","title":"如何在 Linux 中切換相同程序的不同版本","tag":"201808","desc":""},"relativePath":"201808/20180813 How To Switch Between Different Versions Of Commands In Linux.md","filePath":"[post].md"}'),h={name:"201808/20180813 How To Switch Between Different Versions Of Commands In Linux.md"};function c(u,t,g,k,P,b){const e=l("Link");return d(),r("div",null,[t[18]||(t[18]=i("h1",{id:"如何在-linux-中切換相同程序的不同版本",tabindex:"-1"},[s("如何在 Linux 中切換相同程序的不同版本 "),i("a",{class:"header-anchor",href:"#如何在-linux-中切換相同程序的不同版本","aria-label":"Permalink to “如何在 Linux 中切換相同程序的不同版本”"},"​")],-1)),t[19]||(t[19]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/08/alt-tool-720x340.png",alt:""})],-1)),i("p",null,[t[1]||(t[1]=s("幾天前，我們曾經討論",-1)),a(e,{href:"https://www.ostechnix.com/how-to-switch-between-multiple-php-versions-in-ubuntu/"},{default:n(()=>[...t[0]||(t[0]=[s("如何在不同的 PHP 版本之間進行切換",-1)])]),_:1}),t[2]||(t[2]=p("。在那篇文章中，我們使用 <code>update-alternatives</code> 命令實現從一個 PHP 版本切換到另一個 PHP 版本。也就是説，<code>update-alternatives</code> 命令可以將<ruby>系統範圍<rt>system wide</rt></ruby>默認使用的 PHP 版本設置為我們希望的版本。通俗的來説，你可以通過 <code>update-alternatives</code> 命令從系統範圍設置程序的版本。如果你希望可以在不同目錄動態設置不同的程序版本，該如何完成呢？在這種情況下，<code>alt</code> 工具可以大顯身手。<code>alt</code> 是一個命令列工具，可以讓你在類 Unix 系統中切換相同程序的不同版本。該工具簡單易用，是 Rust 語言編寫的自由、開源軟件。",13))]),t[20]||(t[20]=p(`<h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3><p>安裝 <code>alt</code> 工具十分簡單。</p><p>運行如下命令，即可在 Linux 主機上安裝 <code>alt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -sL https://github.com/dotboris/alt/raw/master/install.sh | bash -s</span></span></code></pre></div><p>下一步，將 <code>shims</code> 目錄添加到你的 PATH 環境變量中，具體操作取決於你使用的 Shell。</p><p>對於 Bash：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;export PATH=&quot;$HOME/.local/alt/shims:$PATH&quot;&#39; &gt;&gt; ~/.bashrc</span></span>
<span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>對於 Zsh：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;export PATH=&quot;$HOME/.local/alt/shims:$PATH&quot;&#39; &gt;&gt; ~/.zshrc</span></span>
<span class="line"><span>$ source ~/.zshrc</span></span></code></pre></div><p>對於 Fish：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;set -x PATH &quot;$HOME/.local/alt/shims&quot; $PATH&#39; &gt;&gt; ~/.config/fish/config.fish</span></span></code></pre></div><p>現在 <code>alt</code> 已經安裝完畢！</p><h3 id="使用-alt-工具在-linux-系統中切換相同程序的不同版本" tabindex="-1">使用 alt 工具在 Linux 系統中切換相同程序的不同版本 <a class="header-anchor" href="#使用-alt-工具在-linux-系統中切換相同程序的不同版本" aria-label="Permalink to “使用 alt 工具在 Linux 系統中切換相同程序的不同版本”">​</a></h3><p>如我之前所述，alt 隻影響當前目錄。換句話説，當你進行版本切換時，只在當前目錄生效，而不是整個系統範圍。</p><p>下面舉例説明。我在我的 Ubuntu 系統中安裝了兩個版本的 PHP，分別為 PHP 5.6 和 PHP 7.2；另外，在 <code>myproject</code> 目錄中包含一些 PHP 應用。</p><p>首先，通過命令查看系統範圍默認的 PHP 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ php -v</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Find-PHP-version.png" alt="查找 PHP 版本"></p><p>如截圖中所示，我係統中默認的 PHP 版本為 PHP 7.2。</p><p>然後，我將進入放置 PHP 應用的 <code>myproject</code> 目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd myproject</span></span></code></pre></div><p>使用如下命令掃描可用的 PHP 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alt scan php</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/alt-scan-php.png" alt="掃描 PHP 版本"></p><p>可見，我有兩個 PHP 版本，即 PHP 5.6 和 PHP 7.2。按下 <code>&lt;空格&gt;</code> 鍵選中當前可用的版本。選中全部可用版本後，你可以看到圖中所示的<ruby>叉號<rt>cross mark</rt></ruby>。使用上下方向鍵在版本間移動，點擊回車即可保存變更。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Select-php-version.png" alt="選取 PHP 版本"></p><p>下面運行該命令並選取我們希望在 <code>myproject</code> 目錄中使用的 PHP 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alt use php</span></span></code></pre></div><p>我希望使用 PHP5.6 版本，故我（使用方向鍵）選取該版本並點擊回車鍵。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/set-php-version.png" alt="設置 PHP 版本"></p><p>現在，你可以在 <code>/home/sk/myproject</code> 目錄下使用 PHP 5.6 版本啦。</p><p>讓我們檢查一下，在 <code>myproject</code> 目錄下是否默認使用 PHP 5.6 版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ php -v</span></span></code></pre></div><p>示例輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Check-PHP-version.png" alt="檢查 PHP 版本"></p><p>只要你不設置成其它版本，（在該目錄下）將一直使用 PHP 5.6 版本。清楚了嗎？很好！請注意，我們僅在這個目錄下使用 PHP 5.6 版本。在系統範圍內（LCTT 譯註：當然是沒單獨設置過其它版本的目錄下），PHP 7.2 仍是默認的版本。讓我們檢驗一下，請看下圖。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Check-PHP-version-1.png" alt="比對 PHP 版本"></p><p>從上面的截圖中可以看出，我有兩個版本的 PHP：在 <code>myproject</code> 目錄下，使用的版本為 PHP 5.6；在 <code>myproject</code> 外的其它目錄，使用的版本為 PHP 7.2。</p><p>同理，你可以為每個目錄設置你希望的程序版本。我這裏使用 PHP 僅用於説明操作，但方法適用於任何你打算使用的軟件，例如 NodeJS 等。</p><p>下面是 NodeJS 的示例視頻。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/08/Alt-NodeJS-demo.gif" alt=""></p><p>如果你希望在不同軟件包版本下測試你的應用，那麼 <code>alt</code> 是你不錯的選擇。</p><p>本次分享到此結束。後續還有更多內容，敬請期待！</p><p>乾杯！</p><hr>`,47)),i("p",null,[t[4]||(t[4]=s("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-switch-between-different-versions-of-commands-in-linux/"},{default:n(()=>[...t[3]||(t[3]=[s("https://www.ostechnix.com/how-to-switch-between-different-versions-of-commands-in-linux/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=s("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...t[5]||(t[5]=[s("SK",-1)])]),_:1}),t[10]||(t[10]=s(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[6]||(t[6]=[s("lujun9972",-1)])]),_:1}),t[11]||(t[11]=s(" 譯者：",-1)),a(e,{href:"https://github.com/pinewall"},{default:n(()=>[...t[7]||(t[7]=[s("pinewall",-1)])]),_:1}),t[12]||(t[12]=s(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[s("Linux中國",-1)])]),_:1}),t[17]||(t[17]=s(" 榮譽推出",-1))])])}const x=o(h,[["render",c]]);export{w as __pageData,x as default};
